contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(minSum <= depositAmount);
        require(collectAmount <= depositAmount);
        require(collectAmount >= minSum);
        require(address(this).balance >= depositAmount);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint cBalBefore = address(c).balance;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint cBalAfterDeposit = address(c).balance;

        uint balAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool collectReverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        uint cBalAfterCollect = address(c).balance;
        uint balAfterCollect = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            cBalAfterDeposit == cBalBefore + depositAmount &&
            balAfterDeposit == depositAmount &&
            !collectReverted &&
            cBalAfterCollect == cBalAfterDeposit - collectAmount &&
            balAfterCollect == balAfterDeposit - collectAmount
        );
    }

    receive() external payable {}
}

