pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmount, uint256 minSum, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(minSum <= depositAmount);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(collectAmount >= minSum);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint cBalBefore = address(c).balance;
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint cBalAfterDeposit = address(c).balance;
        uint256 balAfterDeposit;
        try c.balances(address(this)) returns (uint256 __r) { balAfterDeposit = __r; } catch { return; }
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint cBalAfterCollect = address(c).balance;
        uint256 balAfterCollect;
        try c.balances(address(this)) returns (uint256 __r) { balAfterCollect = __r; } catch { return; }
        assertTrue(cBalAfterDeposit == cBalBefore + depositAmount &&
            balAfterDeposit == depositAmount &&
            !collectReverted &&
            cBalAfterCollect == cBalAfterDeposit - collectAmount &&
            balAfterCollect == balAfterDeposit - collectAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        _run(depositAmount, minSum, collectAmount);
    }

    receive() external payable {}
}
